import styled from '@emotion/styled';

export const TagBox = styled.div({
  padding: '2px 8px',
  border: '1px solid rgba(0, 0, 0, 0.16)',
  borderRadius: '4px',
  display: 'flex',
  alignItems: 'center',
  gap: '4px',
  width: 'fit-content',
  color: 'rgba(88, 88, 88, 1)',
});
